import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Frontend web — Interfaces que se sienten al instante","description":"React, Vue, Next.js, Tailwind, gestión de estado y accesibilidad — construyendo interfaces web rápidas y modernas.","frontmatter":{"title":"Frontend web — Interfaces que se sienten al instante","description":"React, Vue, Next.js, Tailwind, gestión de estado y accesibilidad — construyendo interfaces web rápidas y modernas."},"headers":[],"relativePath":"es/skills/web/index.md","filePath":"es/skills/web/index.md"}`),a={name:`es/skills/web/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="frontend-web-—-interfaces-que-se-sienten-al-instante" tabindex="-1">Frontend web — Interfaces que se sienten al instante <a class="header-anchor" href="#frontend-web-—-interfaces-que-se-sienten-al-instante" aria-label="Permalink to “Frontend web — Interfaces que se sienten al instante”">​</a></h1><p>El frontend es donde los usuarios juzgan todo lo que nunca verán. Construyo interfaces que cargan rápido, degradan con gracia y se sienten inmediatas — porque un backend hermoso detrás de una UI torpe es un árbol cayendo en un bosque vacío.</p><h2 id="la-caja-de-herramientas" tabindex="-1">La caja de herramientas <a class="header-anchor" href="#la-caja-de-herramientas" aria-label="Permalink to “La caja de herramientas”">​</a></h2><table tabindex="0"><thead><tr><th>Preocupación</th><th>Herramientas</th></tr></thead><tbody><tr><td>Frameworks</td><td>React, Vue, Angular, Next.js, Nuxt</td></tr><tr><td>Estilos</td><td>Tailwind CSS, arquitectura CSS, design tokens, sistemas responsivos</td></tr><tr><td>Estado</td><td>Pinia, Zustand, Redux Toolkit, cachés de query</td></tr><tr><td>Móvil y escritorio</td><td>React Native, Expo, Flutter, Ionic, Electron, Tauri</td></tr><tr><td>Rendimiento</td><td>Code splitting, presupuesto de imágenes, Core Web Vitals</td></tr></tbody></table><p>Este mismo sitio es una demostración en funcionamiento: un clon del tema VitePress adaptado a dos idiomas con un sistema de iconos SVG propio y un set de ilustraciones generado. El dashboard de <a href="/Usf/es/projects/taskflow-api/">TaskFlow API</a> sigue las mismas reglas bajo restricciones mucho más duras: APIs rápidas con frontends pulidos y responsivos.</p><div class="tip custom-block"><p class="custom-block-title">Lo responsivo es una función</p><p>La mayoría de mis visitantes llega desde un teléfono y una red lenta. Tratar la responsividad y el peso como una ocurrencia tardía es enviar un producto roto — así que diseño para ambos desde el primer commit.</p></div>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};